import "server-only";
import { requireOrgActionAccess } from "@/app/api/internal/lib/organization-access";
import { problemForbidden, problemInternalError, successResponse } from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";
import { canGrantOrganizationWriteAccess } from "@/modules/organization/settings/api-keys/lib/organization-access";

/**
 * Rotate an API key's secret. Needs the same capability as creating one (`organization.manage_api_keys`
 * is checked through the key's organization). A key that carries `accessControl.write` is a user-management
 * credential, so rotating it, which mints a fresh secret for it, also clears the user-management floor,
 * exactly as creating it did (ENG-3075). A missing key and one the caller may not manage get the same 403.
 */
export async function rotateApiKeyOperation({
  authentication,
  apiKeyId,
  requestId,
  instance,
  auditLog,
}: {
  authentication: TV3Authentication;
  apiKeyId: string;
  requestId: string;
  instance?: string;
  auditLog?: TV3AuditLog;
}): Promise<Response> {
  if (auditLog) auditLog.targetId = apiKeyId;

  let organizationId: string;
  try {
    organizationId = await getOrganizationIdFromApiKeyId(apiKeyId);
  } catch {
    return problemForbidden(requestId, undefined, instance);
  }

  const access = await requireOrgActionAccess({
    authentication,
    organizationId,
    action: "organization.manage",
    requestId,
    instance,
  });
  if (access instanceof Response) return access;
  if (auditLog) auditLog.organizationId = access.organizationId;

  try {
    const rotated = await rotateApiKey(apiKeyId);

    if (
      rotated.organizationAccess?.accessControl?.write === true &&
      !(await canGrantOrganizationWriteAccess(access.userId, access.organizationId))
    ) {
      return problemForbidden(requestId, "User management is not allowed for your role", instance);
    }

    return successResponse(rotated, { requestId });
  } catch {
    return problemInternalError(requestId, "Unable to rotate API key", instance);
  }
}
EOF
